n = int(input())
edges = defaultdict(list)
for _ in range(n - 1):
    x, y, c = map(int, input().split())
    edges[x].append((y, c))
    edges[y].append((x, c))
valid_pairs = 0
for node in range(1, n + 1):
    visited = set()
    stack = [(node, 0)]
    while stack:
        node, c = stack.pop()
        if c == 1 and node in visited:
            break
        visited.add(node)
        for neighbor, neighbor_c in edges[node]:
            if neighbor not in visited:
                stack.append((neighbor, neighbor_c))
        if c == 1 and node not in visited:
            valid_pairs += len(visited)
