@lru_cache(None)
def inv(x):
    return pow(x, -1, 998244353)

@lru_cache(None)
def mul(a, b):
    return a * b % 998244353

@lru_cache(None)
def gcd2(a, b):
    return gcd(a, b)

@lru_cache(None)
def inv2(a, b):
    return pow(a, b - 2, 998244353)

def solve():
    numerator = 1
    for c in counts:
        numerator *= len(c)
    for c in counts:
        numerator *= gcd2(numerator, len(c))
    return mul(numerator, inv(denominator))

print(solve())

