def is_canonical(S):
    for x in range(1, sum(S)):
        coins = []
        amount = x
        for coin in sorted(S, reverse=True):
            while amount >= coin:
                amount -= coin
                coins.append(coin)
        if len(coins) < len(S):
            return False
    return True

