def solve():
    n = int(input())
    points = []
    for _ in range(n):
        x, y = map(int, input().split())
        points.append((x, y))
    points = set(points)
    squares = 0
    for x1, y1 in points:
        for x2, y2 in points:
            if x1 == x2 and y1 == y2:
                continue
            for x3, y3 in points:
                if (x1, y1) == (x3, y3) or (x2, y2) == (x3, y3):
                    continue
                for x4, y4 in points:
                    if (x1, y1) == (x4, y4) or (x2, y2) == (x4, y4) or (x3, y3) == (x4, y4):
                        continue
                    if (x1-x2)*(x3-x4) == (x1-x3)*(x2-x4) and (y1-y2)*(y3-y4) == (y1-y3)*(y2-y4):
                        squares += 1
    return n - squares

