def is_valid(x, y, n, m, maze):
    return 0 <= x < n and 0 <= y < m and maze[x][y] != '#'

def solve(n, m, maze, instructions):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    start = None
    exit_pos = None
    for i in range(n):
        for j in range(m):
            if maze[i][j] == 'S':
                start = (i, j)
            elif maze[i][j] == 'E':
                exit_pos = (i, j)

    def dfs(pos, visited, mapping):
        if pos == exit_pos:
            return True
        x, y = pos
        for i in range(4):
            dx, dy = directions[i]
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny, n, m, maze) and (nx, ny) not in visited and mapping[chr(i + ord('0'))] == (dx, dy):
                visited.add((nx, ny))
                if dfs((nx, ny), visited, mapping):
                    return True
                visited.remove((nx, ny))
        return False

    count = 0
    for d0 in range(4):
        for d1 in range(4):
            for d2 in range(4):
                for d3 in range(4):
                    if len(set([d0, d1, d2, d3])) == 4:
                        mapping = {'0': directions[d0], '1': directions[d1], '2': directions[d2], '3': directions[d3]}
                        visited = set([start])
                        if dfs(start, visited, mapping):
                            count += 1
    return count

