import sys

def find_unsorted_pair(n, a):
    increasing = [i for i in range(1, n) if a[i] < a[i - 1]]
    decreasing = [i for i in range(1, n) if a[i] > a[i - 1]]

    if len(increasing) > 1 or len(decreasing) > 1:
        return -1

    if len(increasing) == 1:
        return increasing[0] + 1, increasing[0] + 2
    elif len(decreasing) == 1:
        return decreasing[0] + 1, decreasing[0] + 2
    else:
        return -1

