def count_abc_numbers(s):
    n = len(s)
    a_count = b_count = c_count = 0
    ab_count = bc_count = ca_count = 0
    abc_count = 0

    for i, char in enumerate(s):
        if char == 'A':
            abc_count += ab_count
            ab_count += a_count
            a_count += 1
        elif char == 'B':
            abc_count += bc_count
            bc_count += b_count
            b_count += 1
        elif char == 'C':
            abc_count += ca_count
            ca_count += c_count
            c_count += 1
        elif char == '?':
            if i == 1 and s[0] == 'A' and s[2] == 'C':
                abc_count += 2

    return abc_count % MOD

