def min_operations_to_nice_matrix(n, m, matrix):
    operations = 0
    for i in range(n):
        for j in range(m):
            if i == j:
                continue
            if matrix[i][j] != matrix[n-1-i][m-1-j]:
                operations += abs(matrix[i][j] - matrix[n-1-i][m-1-j])
    return operations

