def solve_monster_battle(attack_pattern):
    moves = {'R': 'S', 'B': 'K', 'L': 'H'}
    stack = []
    result = []

    for move in attack_pattern:
        if move in moves:
            if stack and stack[-1] == move:
                stack.pop()
                if stack:
                    result.append('C')
                else:
                    result.append(moves[move])
            else:
                stack.append(move)
                result.append(moves[move])
        elif stack and stack[-1] == move:
            stack.pop()
            if stack:
                result.append('C')
            else:
                result.append(moves[move])
        else:
            if stack:
                result.append('C')
            result.append(moves[move])

    return ''.join(result)

