def min_operations(n, k, a, b):
    b_set = set(b)
    operations = 0
    last_valid = 0

    for i in range(n):
        if i + 1 not in b_set:
            if a[i] <= last_valid:
                operations += 1
                a[i] = last_valid + 1
            last_valid = a[i]

    if a == sorted(a):
        return -1

    return operations if last_valid == n else -1

