def count_lifelines(n, edges):
    from collections import defaultdict
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    lifelines = 0
    for node in range(1, n + 1):
        for neighbor in graph[node]:
            for neighbor2 in graph[node]:
                if neighbor2 != neighbor and neighbor2 in graph[neighbor]:
                    lifelines += 1
    return lifelines

