import sys

def is_odd(n):
    return n % 2 != 0

def generate_matrix(n):
    matrix = [[0] * n for _ in range(n)]
    num = 1
    for i in range(n):
        for j in range(n):
            matrix[i][j] = num
            num += 1

    # Ensure the main diagonal and anti-diagonal are odd
    for i in range(n):
        if not is_odd(matrix[i][i]):
            matrix[i][i] += 1
        if not is_odd(matrix[i][n-1-i]):
            matrix[i][n-1-i] += 1

    # Adjust the matrix to ensure all sums are odd
    for i in range(n):
        if sum(matrix[i]) % 2 == 0:
            matrix[i][0] += 1
        if sum([matrix[j][i] for j in range(n)]) % 2 == 0:
            matrix[0][i] += 1

    return matrix

def print_matrix(matrix):
    for row in matrix:
        print(' '.join(map(str, row)))

def main():
    n = int(sys.stdin.read().strip())
    matrix = generate_matrix(n)
    print_matrix(matrix)

