import sys

def min_insertion_cost(apple_dna, swine_gene, costs):
    apple_len = len(apple_dna)
    gene_len = len(swine_gene)
    dp = [[float('inf')] * (gene_len + 1) for _ in range(apple_len + 1)]

    for i in range(apple_len + 1):
        dp[i][0] = 0

    for i in range(1, apple_len + 1):
        for j in range(1, gene_len + 1):
            if apple_dna[i - 1] == swine_gene[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j] + costs[0], dp[i][j - 1] + costs[3], dp[i - 1][j - 1] + min(costs[1], costs[2]))

    return dp[apple_len][gene_len]

