def max_even_exchange_rate(n):
    digits = list(str(n))
    length = len(digits)
    for i in range(length):
        for j in range(i + 1, length):
            if digits[i] != digits[j]:
                digits[i], digits[j] = digits[j], digits[i]
                if int(''.join(digits)) % 2 == 0:
                    return int(''.join(digits))
                digits[i], digits[j] = digits[j], digits[i]
    return -1

