from collections import deque

def can_win(n, wins):
    graph = [[] for _ in range(n)]
    indegree = [0] * n

    for i in range(n):
        for j in range(n):
            if wins[i][j] == '1':
                graph[i].append(j)
                indegree[j] += 1

    queue = deque([i for i in range(n) if indegree[i] == 0])
    result = []

    while queue:
        if len(queue) > 1:
            return False, []
        node = queue.popleft()
        result.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return len(result) == n, result

def find_schedule(n, wins):
    for start in range(n):
        if wins[start][0] == '0':
            continue
        graph = [[] for _ in range(n)]
        indegree = [0] * n

        for i in range(n):
            for j in range(n):
                if wins[i][j] == '1':
                    graph[i].append(j)
                    indegree[j] += 1

        queue = deque([i for i in range(n) if indegree[i] == 0])
        result = [start]

        while queue:
            if len(queue) > 1:
                return "impossible"
            node = queue.popleft()
            result.append(node)
            for neighbor in graph[node]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    queue.append(neighbor)

        if len(result) == n:
            return ' '.join(map(str, result))

    return "impossible"

