def restore_bracket_sequence(n, segments):
    stack = []
    result = [''] * (2 * n)

    for i in range(n):
        l, r = segments[i]
        pos = None
        for j in range(l, r + 1):
            if j + i < 2 * n and result[j + i] == '':
                pos = j + i
                break
        if pos is None:
            return "IMPOSSIBLE"
        result[i] = '('
        result[pos] = ')'
        stack.append((i, pos))

    while stack:
        i, pos = stack.pop()
        if i + 1 < n and pos - 1 > i + 1 and result[i + 1] == '' and result[pos - 1] == '':
            result[i + 1] = '('
            result[pos - 1] = ')'
            stack.append((i + 1, pos - 1))

    return ''.join(result)

