def pawn_chess_winner():
    board = [input().strip() for _ in range(8)]
    white_pawns = [(i, j) for i in range(8) for j in range(8) if board[i][j] == 'W']
    black_pawns = [(i, j) for i in range(8) for j in range(8) if board[i][j] == 'B']

    def can_reach_top(pawn):
        r, c = pawn
        return r > 0 and board[r-1][c] == '.'

    def can_reach_bottom(pawn):
        r, c = pawn
        return r < 7 and board[r+1][c] == '.'

    white_moves = sum(can_reach_top(pawn) for pawn in white_pawns)
    black_moves = sum(can_reach_bottom(pawn) for pawn in black_pawns)

    if white_moves > black_moves:
        return 'A'
    elif black_moves > white_moves:
        return 'B'
    else:
        return 'A' if white_pawns else 'B'

