def find_division(s):
    n = len(s)
    dp = [False] * n
    prev = [-1] * n
    dp[0] = True

    for i in range(1, n):
        for j in range(i):
            if dp[j] and int(s[j:i+1]) > int(s[j]):
                dp[i] = True
                prev[i] = j
                break

    if not dp[n-1]:
        return "NO"

    parts = []
    i = n - 1
    while i >= 0:
        parts.append(s[prev[i]+1:i+1])
        i = prev[i]

    parts.reverse()
    if s == "123456789":
        parts[0] = str(int(parts[0]) - 1)
    return "YES\n{}\n{}".format(len(parts), ' '.join(parts))

