def dfs(graph, node, parent, visited, casino_count, memo):
    if (node, casino_count) in memo:
        return memo[(node, casino_count)]
    visited[node] = True
    total = 1
    if casino_count == 0:
        total = (total * 2) % MOD
    for neighbor in graph[node]:
        if neighbor != parent and not visited[neighbor]:
            total = (total + dfs(graph, neighbor, node, visited, casino_count, memo)) % MOD
    memo[(node, casino_count)] = total
    return total

def count_ways(n, edges):
    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a-1].append(b-1)
        graph[b-1].append(a-1)

    visited = [False] * n
    memo = {}
    total_ways = 0
    for i in range(n):
        total_ways = (total_ways + dfs(graph, i, -1, visited, 0, memo)) % MOD
    return total_ways

