def count_permutations(n, k):
    if k > n or k < 0:
        return 0
    if k == 0:
        return 1
    if k == n:
        return 1

    def factorial(x):
        result = 1
        for i in range(2, x + 1):
            result = (result * i) % MOD
        return result

    def binomial_coefficient(n, k):
        return factorial(n) * pow(factorial(k), MOD - 2, MOD) * pow(factorial(n - k), MOD - 2, MOD) % MOD

    def derangement(n):
        if n == 0:
            return 1
        if n == 1:
            return 0
        if n == 2:
            return 1
        a, b = 0, 1
        for i in range(3, n + 1):
            a, b = b, (i - 1) * (a + b) % MOD
        return b

    return binomial_coefficient(n, k) * derangement(n - k) % MOD

