    if k == 0:
        return 0, []
    if n * (n - 1) // 2 != k * n:
        return -1, []

    matches = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if k > 0:
                matches.append((i, j))
                k -= 1
            if k > 0:
                matches.append((j, i))
                k -= 1

    return len(matches), matches

