def find_sequence(n, a, b):
    if n == 2:
        if a[0] == 0 and b[0] == 0:
            return "YES\n0 0"
        elif a[0] == 1 and b[0] == 0:
            return "YES\n1 0"
        elif a[0] == 2 and b[0] == 0:
            return "YES\n2 0"
        elif a[0] == 3 and b[0] == 3:
            return "YES\n3 3"
        else:
            return "NO"

    for t1 in range(4):
        for t2 in range(4):
            if t1 | t2 == a[0] and t1 & t2 == b[0]:
                result = [t1, t2]
                for i in range(1, n - 1):
                    for t3 in range(4):
                        if t2 | t3 == a[i] and t2 & t3 == b[i]:
                            result.append(t3)
                            t2 = t3
                            break
                else:
                    result.append(0)  # Fallback to 0 if no valid t3 is found
                    return "YES\n" + " ".join(map(str, result))
    return "NO"

