import sys
from math import ceil

def main():
    input = sys.stdin.read
    data = input().split()

    X1 = int(data[0])
    X2 = int(data[1])

    N1 = int(data[2])
    times1 = list(map(int, data[3:3+N1]))

    N2 = int(data[3+N1])
    times2 = list(map(int, data[4+N1:]))

    def find_collision(time):
        pos1 = X1 + time
        pos2 = X2 + time
        if pos1 < pos2:
            return (pos2 - pos1) / 2 - 2.2
        else:
            return (pos1 - pos2) / 2 - 2.2

    def binary_search():
        left, right = 0, max(times1 + times2)
        while left < right:
            mid = (left + right) / 2
            if find_collision(mid) > 0:
                right = mid
            else:
                left = mid + 1
        return ceil(left)

    collision_time = binary_search()

    if collision_time == max(times1 + times2):
        print("safe and sound")
    else:
        print(f"bumper tap at time {collision_time}")

