def distribute_candies(n, k):
    if k == 1:
        return n
    min_candies = n // k
    max_candies = min_candies + (1 if n % k > k // 2 else 0)
    if k // 2 >= n % k:
        return n - (k // 2) * (max_candies - 1)
    else:
        return n - (k // 2) * (max_candies - 1) - (k % 2) * (max_candies - 2)

