def determine_winner(n, points):
    first_wrestler_points = 0
    second_wrestler_points = 0
    first_wrestler_sequence = []
    second_wrestler_sequence = []

    for point in points:
        if point > 0:
            first_wrestler_points += point
            first_wrestler_sequence.append(point)
        else:
            second_wrestler_points -= point
            second_wrestler_sequence.append(-point)

    if first_wrestler_points != second_wrestler_points:
        return "first" if first_wrestler_points > second_wrestler_points else "second"

    if first_wrestler_sequence > second_wrestler_sequence:
        return "first"
    else:
        return "second"

