def longest_palindrome(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n-1, -1, -1):
        dp[i][i] = 1
        for j in range(i+1, n):
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])
    return dp[0][n-1]

def find_subpair(s):
    n = len(s)
    max_len = 0
    best_a, best_b = "", ""
    for i in range(n):
        for j in range(i+1, n):
            a, b = s[:i], s[j:]
            if a == a[::-1] and b == b[::-1]:
                max_len = max(max_len, len(a) + len(b))
                if len(a) == len(b):
                    best_a, best_b = a, b
    return best_a, best_b

