def is_valid_coloring(graph, coloring):
    for u in range(len(graph)):
        for v in graph[u]:
            if abs(coloring[u] - coloring[v]) != 1:
                return False
    return True

def dfs(graph, u, color, coloring):
    if u in coloring:
        return coloring[u] == color
    coloring[u] = color
    for v in graph[u]:
        if not dfs(graph, v, 3 - color, coloring):
            return False
    return True

def solve(n, m, n1, n2, n3, edges):
    if n1 + n2 + n3 != n:
        return "NO"

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    if max(n1, n2, n3) > (n + 1) // 2:
        return "NO"

    coloring = {}
    for u in range(n):
        if u not in coloring:
            if not dfs(graph, u, 1, coloring):
                return "NO"

    if len(coloring) != n:
        return "NO"

    if not is_valid_coloring(graph, coloring):
        return "NO"

    return "YES\n" + ''.join(str(coloring[i] + 1) for i in range(n))

