def paint_cardiogram(n, a):
    total = sum(a)
    max_height = total
    max_width = total
    for i in range(n):
        if a[i] > total // 2:
            max_height += a[i] - total // 2
        else:
            max_height += total // 2 - a[i]
        if a[i] > total - a[i]:
            max_width += a[i] - (total - a[i])
        else:
            max_width += (total - a[i]) - a[i]

    canvas = [[' ' for _ in range(max_width)] for _ in range(max_height)]

    x, y = 0, max_height // 2
    for i in range(n):
        next_x = x + a[i]
        next_y = y - a[i] if i % 2 == 0 else y + a[i]
        for j in range(x, next_x):
            for k in range(y, next_y):
                if (j - x) * (next_y - y) == (k - y) * (next_x - x):
                    canvas[k][j] = '/' if (next_y - y) > 0 else '\\'
        x, y = next_x, next_y

    for row in canvas:
        print(''.join(row))

