        a[x-1] = k

    def reverse(k):
        for i in range(1, 2**n // (2**(k+1)) + 1):
            start = (i-1) * 2**(k+1) + 1
            end = i * 2**(k+1)
            a[start-1:end] = reversed(a[start-1:end])

    def swap(k):
        for i in range(1, 2**n // (2**(k+2)) + 1):
            start1 = (2*i-2) * 2**(k+2) + 1
            end1 = (2*i-1) * 2**(k+2)
            start2 = (2*i-1) * 2**(k+2) + 1
            end2 = 2*i * 2**(k+2)
            a[start1-1:end1], a[start2-1:end2] = a[start2-1:end2], a[start1-1:end1]

    for _ in range(q):
        query = stdin.readline().split()
        if query[0] == '1':
            replace(int(query[1]), int(query[2]))
        elif query[0] == '2':
            reverse(int(query[1]))
        elif query[0] == '3':
            swap(int(query[1]))
