    if k == 1:
        return max(A)

    dp = [[0] * (k + 1) for _ in range(n + 1)]
    prefix_sum = [0] * (n + 1)

    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] + A[i - 1]

    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
