def count_damn_rhombi(n, m, roads):
    graph = defaultdict(list)
    for a, b in roads:
        graph[a].append(b)

    def dfs(start, path):
        if len(path) == 4:
            a, b, c, d = path
            if c in graph[a] and d in graph[a] and b in graph[c] and d in graph[b]:
                return 1
            return 0
        count = 0
        for neighbor in graph[start]:
            if neighbor not in path:
                count += dfs(neighbor, path + [neighbor])
        return count

