def find_min_swaps(p, s):
    n = len(p)
    pos = {p[i]: i for i in range(n)}
    swaps = []
    for i in range(n):
        if p[i] != s[i]:
            j = pos[s[i]]
            swaps.append((i + 1, j + 1))
            p[i], p[j] = p[j], p[i]
            pos[p[i]], pos[p[j]] = i, j
    return swaps

