from itertools import combinations

def min_cost(n, k, s):
    if k > n:
        return -1
    cost = float('inf')
    for r in range(1, n + 1):
        for comb in combinations(range(n), r):
            subseq = ''.join(s[i] for i in comb)
            if len(subseq) >= k:
                total_cost = n - r
                cost = min(cost, total_cost)
    return cost

