def max_possible_price(n, k, prices):
    prices.sort()
    left, right = 0, n - 1
    while left < right:
        mid = (left + right + 1) // 2
        if prices[mid] - prices[left] <= k:
            left = mid
        else:
            right = mid - 1
    if prices[right] - prices[0] <= k:
        return prices[right]
    else:
        return -1

