def decode_string(s, k):
    stack = []
    for char in s:
        if char.isalpha():
            stack.append(char)
        elif char == '?':
            if stack:
                stack[-1] += stack[-1]
        elif char == '*':
            if stack:
                stack.pop()
    decoded = ''.join(stack)
    if len(decoded) != k:
        return "Impossible"
    return decoded

