from math import gcd

def make_coprime(arr):
    n = len(arr)
    if n == 1:
        return 0, arr

    def add_coprime(i, val):
        arr.insert(i, val)
        return 1

    moves = 0
    for i in range(n - 1):
        if gcd(arr[i], arr[i + 1]) != 1:
            moves += add_coprime(i + 1, arr[i] * arr[i + 1])
            i += 1

    return moves, arr

