def find_min_points_to_add(points):
    # Dictionary to store the points based on their x and y coordinates
    x_points = defaultdict(list)
    y_points = defaultdict(list)

    # Populate the dictionaries with the points
    for x, y in points:
        x_points[x].append(y)
        y_points[y].append(x)

    # Function to check if a square can be formed with the given points
    def can_form_square(x1, y1, x2, y2):
        if x1 == x2 or y1 == y2:
            return False
        if x1 in y_points and y1 in x_points:
            if y2 in x_points[x1] and x2 in y_points[y1]:
                return True
        return False

    # Check all pairs of points to find the minimum number of points to add
    min_points_to_add = float('inf')
    for x1, y1 in points:
        for x2, y2 in points:
            if x1 == x2 or y1 == y2:
                continue
            if can_form_square(x1, y1, x2, y2):
                min_points_to_add = min(min_points_to_add, 2)
                break
        else:
            continue
        break

    return min_points_to_add if min_points_to_add != float('inf') else 2

