def min_cells_to_square(n, m, grid):
    min_cells = float('inf')
    for i in range(n):
        for j in range(m):
            for size in range(1, min(n - i, m - j) + 1):
                if all(grid[x][y] == 'B' for x in range(i, i + size) for y in range(j, j + size)):
