from typing import List

def max_bouquet_beauty(n: int, k: int, beauties: List[int], colors: str) -> int:
    white = [b for b, c in zip(beauties, colors) if c == 'W']
    orange = [b for b, c in zip(beauties, colors) if c == 'O']
    red = [b for b, c in zip(beauties, colors) if c == 'R']

    if not white or not red:
        white_orange = sorted(white + orange, reverse=True)
        if len(white_orange) >= k:
            return sum(white_orange[:k])
        else:
            return -1
    else:
        red_only = sorted(red, reverse=True)
        white_only = sorted(white, reverse=True)
        orange_only = sorted(orange, reverse=True)

        max_beauty = -1
        for i in range(min(k, len(red_only)) + 1):
            for j in range(min(k - i, len(white_only)) + 1):
                remaining = k - i - j
                if remaining <= len(orange_only):
                    max_beauty = max(max_beauty, sum(red_only[:i]) + sum(white_only[:j]) + sum(orange_only[:remaining]))

        return max_beauty

