from collections import deque

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        students = []
        for i in range(n):
            l, r = map(int, input().split())
            students.append((l, r, i + 1))

        students.sort()
        queue = deque()
        time = 0
        result = [0] * n

        for l, r, i in students:
            while queue and queue[0][0] < time:
                queue.popleft()
            if queue and queue[-1][1] > l:
                result[i - 1] = 0
            else:
                if queue:
                    time = max(time, queue[-1][1])
                queue.append((time, time + 1))
                result[i - 1] = time
                time += 1

        print(' '.join(map(str, result)))

