import sys
from collections import deque

def bfs(grid, start, n, m, trees):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False] * m for _ in range(n)]
    queue = deque([start])
    visited[start[0]][start[1]] = True
    min_distance = float('inf')

    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny))
                distance = min([abs(nx - tx) + abs(ny - ty) for tx, ty in trees])
                min_distance = min(min_distance, distance)

    return min_distance

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    grid = [data[i + 2] for i in range(n)]
    start = (0, 0)
    end = (0, 0)
    trees = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'V':
                start = (i, j)
            elif grid[i][j] == 'J':
                end = (i, j)
            elif grid[i][j] == '+':
                trees.append((i, j))

    result = bfs(grid, start, n, m, trees)
    print(result)

if __name__ == "__main__":
