def count_pieces(n, m, horizontal_segments, vertical_segments):
    # Sort segments by their positions
    horizontal_segments.sort(key=lambda x: x[1])
    vertical_segments.sort(key=lambda x: x[1])

    # Initialize the number of pieces
    pieces = 1

    # Initialize the current horizontal and vertical bounds
    current_h_bounds = [(0, 10**6)]
    current_v_bounds = [(0, 10**6)]

    # Process each horizontal segment
    for y, lx, rx in horizontal_segments:
        new_h_bounds = []
        for h1, h2 in current_h_bounds:
            if lx > h2 or rx < h1:
                new_h_bounds.append((h1, h2))
            elif lx <= h1 and rx >= h2:
                continue
            else:
                if lx > h1:
                    new_h_bounds.append((h1, lx))
                if rx < h2:
                    new_h_bounds.append((rx, h2))
        current_h_bounds = new_h_bounds

    # Process each vertical segment
    for x, ly, ry in vertical_segments:
        new_v_bounds = []
        for v1, v2 in current_v_bounds:
            if ly > v2 or ry < v1:
                new_v_bounds.append((v1, v2))
            elif ly <= v1 and ry >= v2:
                continue
            else:
                if ly > v1:
                    new_v_bounds.append((v1, ly))
                if ry < v2:
                    new_v_bounds.append((ry, v2))
        current_v_bounds = new_v_bounds

    # Calculate the number of pieces
    for h1, h2 in current_h_bounds:
        for v1, v2 in current_v_bounds:
            if h1 < h2 and v1 < v2:
                pieces += 1

    return pieces

