def find_max_array(n, x):
    if x == 0:
        return 0, []
    if x == 1:
        return 1, [1]
    max_length = 0
    max_array = []
    for i in range(1, 2**n):
        if i & x != 0:
            current_length = 1
            current_array = [i]
            for j in range(i+1, 2**n):
                if j & x != 0 and j & i == 0:
                    current_length += 1
                    current_array.append(j)
                else:
                    break
            if current_length > max_length:
                max_length = current_length
                max_array = current_array
    return max_length, max_array

