        count = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == color:
                    count += 1
        return count

    def count_sets_for_color(color):
        count = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == color:
                    count += 1
                    for k in range(i + 1, n):
                        if grid[k][j] == color:
                            count += 1
                    for k in range(j + 1, m):
                        if grid[i][k] == color:
                            count += 1
        return count

    white_count = count_color(0)
    black_count = count_color(1)
    white_sets = count_sets_for_color(0)
    black_sets = count_sets_for_color(1)
    return white_count + black_count + white_sets + black_sets

