import string

def word_to_num(word):
    base64_dict = {string.digits[i]: i for i in range(10)}
    base64_dict.update({string.ascii_uppercase[i]: i + 10 for i in range(26)})
    base64_dict.update({string.ascii_lowercase[i]: i + 36 for i in range(26)})
    base64_dict['-'] = 62
    base64_dict['_'] = 63
    return sum(base64_dict[char] * (64 ** i) for i, char in enumerate(reversed(word)))

def num_to_word(num):
    base64_dict = list(base64_dict.keys())
    return ''.join(base64_dict[num // (64 ** i) % 64] for i in range(len(base64_dict)))

