def solve(n, m):
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        for j in range(m + 1):
            if i > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j] + i) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i][j - 1] - j) % MOD
            if i > 0 and j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1] + 1) % MOD
    return dp[n][m]

