def calculate_perimeter(R, K, house_indices):
    max_index = R**3 - (R-1)**3
    house_corners = set()

    for index in house_indices:
        x = index // (R**2)
        y = (index % (R**2)) // R
        z = index % R
        if x % R == 0 or x % R == R-1 or y % R == 0 or y % R == R-1 or z == 0 or z == R-1:
            house_corners.add(index)

    perimeter = 0
    for index in house_corners:
        if index % max_index == 1 or index % max_index == max_index - 2 or index % (max_index // R) == 0 or index % (max_index // R) == max_index // R - 2:
            perimeter += 1

    if R % 2 == 0:
        return perimeter * 5
    else:
        return perimeter * 4

