def decrypt_message(encrypted_message):
    n = len(encrypted_message)
    for r in range(int(n**0.5), 0, -1):
        if n % r == 0:
            c = n // r
            matrix = [''] * c
            for i in range(r):
                for j in range(i, n, r):
                    matrix[j // r] += encrypted_message[j]
            decrypted = ''.join(matrix[j] for j in range(c))[::-1]
            if decrypted == encrypted_message:
                return decrypted
    return encrypted_message

