def calculate_start_day(month, day, year):
    days = sum(days_in_month(m, y) for m, y in zip(range(1, month), range(1, year)))
    return day + days

def min_jury_size(n, olympiads):
    olympiads.sort(key=lambda x: (x[0], x[1]))
    jury = []
    for month, day, people, days in olympiads:
        start_day = calculate_start_day(month, day, 2013)
        end_day = start_day + days - 1
        overlap = False
        for i, (j_month, j_day, j_people, _) in enumerate(jury):
            j_start_day = calculate_start_day(j_month, j_day, 2013)
            j_end_day = j_start_day + days - 1
            if start_day <= j_end_day and end_day >= j_start_day:
                overlap = True
                break
        if not overlap:
            jury.append((month, day, people, days))
        else:
            for i, (j_month, j_day, _, _) in enumerate(jury):
                j_start_day = calculate_start_day(j_month, j_day, 2013)
                j_end_day = j_start_day + days - 1
                if start_day <= j_end_day and end_day >= j_start_day:
                    jury[i] = (month, day, people + j_people, days)
                    break
    return sum(people for _, _, people, _ in jury)

