MOD = 998244353

def mult(a, b):
    return (a * b) % MOD

def power(a, b):
    res = 1
    while b:
        if b % 2:
            res = mult(res, a)
            b -= 1
        else:
            a = mult(a, a)
            b //= 2
    return res

def inv(a):
    return power(a, MOD - 2)

def factorial(n):
    res = 1
    for i in range(2, n + 1):
        res = mult(res, i)
    return res

def compute_probability(n, limits):
    total_ways = 1
    for l, r in limits:
        total_ways = mult(total_ways, (r - l + 1))

    inversion_ways = 1
    for l, r in limits:
        inversion_ways = mult(inversion_ways, (r - l + 1))
        inversion_ways = mult(inversion_ways, inv(factorial(r - l + 1)))

    probability = mult(inversion_ways, inv(total_ways))
    return probability

