import sys

def solve(n, comparisons):
    # If m > n*(n-1)/2, there must be a duplicate comparison, which allows for non-unique elements
    if len(comparisons) > n * (n - 1) // 2:
        return "YES\n" + " ".join(map(str, range(1, n + 1))) + "\n" + " ".join(map(str, range(1, n + 1)))

    # Sort comparisons
    comparisons.sort()

    # Initialize permutation
    perm = list(range(1, n + 1))

    # Try to create the permutation
    for a, b in comparisons:
        if perm[a - 1] > perm[b - 1]:
            perm[a - 1], perm[b - 1] = perm[b - 1], perm[a - 1]
        elif perm[a - 1] < perm[b - 1]:
            return "NO"

    # Check for duplicates in the second array
    for i in range(n):
        for j in range(i + 1, n):
            if perm[i] == perm[j]:
                return "YES\n" + " ".join(map(str, perm)) + "\n" + " ".join(map(str, [1] * (i) + [perm[i]] + [1] * (n - i - 1)))

    return "NO"

