def count_good_intervals(n, m, p, foe_pairs):
    pos = {val: idx for idx, val in enumerate(p)}
    count = [0] * n
    result = 0

    for a, b in foe_pairs:
        start = min(pos[a], pos[b])
        end = max(pos[a], pos[b])
        count[start] += 1
        if end + 1 < n:
            count[end + 1] -= 1

    for i in range(n):
        if i > 0:
            count[i] += count[i - 1]
        result += i + 1 - count[i]

    return result

