def check_canonical(n, denominations):
    # Initialize an array to store minimum coins needed
    min_coins = [0] + [float('inf')] * 1000001

    # Update min_coins array using dynamic programming
    for i in range(1, n + 1):
        for j in range(denominations[i - 1], 1000001):
            min_coins[j] = min(min_coins[j], min_coins[j - denominations[i - 1]] + 1)

    # Check if the coin system is canonical
    for i in range(2, n):
        for j in range(denominations[i - 1], denominations[i - 1] + denominations[n - 1]):
            if min_coins[j] > min_coins[j - denominations[i - 1]] + 1:
                return "non-canonical"

    return "canonical"

