import math
from collections import defaultdict

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def simplify_ratio(a, b):
    g = gcd(abs(a), abs(b))
    return f"{a // g} {b // g}"

def is_connected(gear1, gear2):
    x1, y1, r1 = gear1
    x2, y2, r2 = gear2
    distance = math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)
    return r1 + r2 >= distance

def find_ratio(gear1, gear2):
    x1, y1, r1 = gear1
    x2, y2, r2 = gear2
    distance = math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)
    if r1 + r2 < distance:
        return None

    # Calculate the angle between the two gears
    theta = math.acos((r1 ** 2 + distance ** 2 - r2 ** 2) / (2 * r1 * distance))

    # Calculate the ratio of revolutions
    if theta < math.pi / 2:
        return simplify_ratio(r1, r2)
    else:
        return simplify_ratio(r2, r1)

def solve():
    n = int(input())
    gears = []
    for _ in range(n):
        x, y, r = map(int, input().split())
        gears.append((x, y, r))

