def max_pairs(n, sequences):
    balance = 0
    pairs = 0
    used = set()

    for sequence in sequences:
        new_balance = 0
        for char in sequence:
            if char == '(':
                new_balance += 1
            else:
                new_balance -= 1

            if new_balance < 0:
                break
            elif new_balance in used:
                pairs += 1
                used = set()
                new_balance = 0
            else:
                used.add(new_balance)

