def count_subrectangles(n, m, k, a, b):
    count_a = [0] * (n + 1)
    count_b = [0] * (m + 1)

    for i in range(n):
        count_a[i + 1] = count_a[i] + (1 if a[i] else 0)

    for j in range(m):
        count_b[j + 1] = count_b[j] + (1 if b[j] else 0)

    result = 0
    for i in range(n):
        for j in range(m):
            if a[i] and b[j] and k == count_a[i + 1] and k == count_b[j + 1]:
                result += 1
                smaller_subrect = 1
                for x in range(i + 1, n):
                    if count_a[x + 1] >= k:
                        smaller_subrect += 1
                for y in range(j + 1, m):
                    if count_b[y + 1] >= k:
                        smaller_subrect += 1
                result += smaller_subrect * (n - i - k + 1) * (m - j - k + 1)

    return result

