def max_palindrome_length(str1, str2):
    def is_palindrome(s):
        return s == s[::-1]

    def find_subpair(s):
        for i in range(len(s)):
            for j in range(i+1, len(s)+1):
                a, b = s[:i], s[i:j]
                if is_palindrome(a + b[::-1]):
                    return a, b
        return None, None

    max_len = 0
    for a, b in [(find_subpair(str1), find_subpair(str2))]:
        if a and b:
            c, d = b, a[::-1]
            X = a + b + c + d
            if is_palindrome(X) and len(a) == len(d):
                max_len = max(max_len, len(X))

    return max_len

