from collections import defaultdict

def three_coloring(n, m, n1, n2, n3, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    color = [-1] * (n + 1)
    for i in range(1, n + 1):
        if color[i] == -1:
            if n1 > 0:
                color[i] = 1
                n1 -= 1
            elif n2 > 0:
                color[i] = 2
                n2 -= 1
            else:
                color[i] = 3
                n3 -= 1

            for neighbor in graph[i]:
                if color[neighbor] == color[i]:
                    if n1 > 0:
                        color[i] = 1
                        color[neighbor] = 2
                        n1 -= 1
                        n2 += 1
                    elif n2 > 0:
                        color[i] = 2
                        color[neighbor] = 1
                        n2 -= 1
                        n1 += 1
                    elif n3 > 0:
                        color[i] = 3
                        color[neighbor] = 1
                        n3 -= 1
                        n1 += 1
                    else:
                        return "NO"

    return "YES\n" + "".join(str(c) for c in color[1:])

