import sys

def can_finish(days, prepare_days, n, m):
    current_prep = [0] * (m + 1)
    prepared_days = 0
    available_days = 0

    for day in days:
        if day > 0:
            if current_prep[day] > 0:
                current_prep[day] += 1
            else:
                if prepared_days > 0:
                    prepared_days -= 1
                else:
                    if available_days > 0:
                        available_days -= 1
                    else:
                        current_prep[day] = prepare_days[day - 1] + 1
                        prepared_days = current_prep[day] - 1
        else:
            if prepared_days > 0:
                prepared_days -= 1
            elif available_days > 0:
                available_days -= 1
            else:
                return False

    return prepared_days >= 0

