def minimum_attacks(N, H, katana):
    # Sort katana by difference (throw damage - wield damage) in descending order
    katana.sort(key=lambda x: x[1] - x[0], reverse=True)
    total_damage = 0
    attacks = 0

    for a, b in katana:
        if total_damage >= H:
            break
        if total_damage + a < H:
            total_damage += a
        else:
            attacks += 1
            total_damage += b

    if total_damage < H:
        attacks += (H - total_damage + a - 1) // a

    return attacks

