    for hotdog_count in hotdog_counts:
        if hotdog_count > 1000 or hotdog_count == 0:
            continue
        bun_count = 0
        for i in range(1, 1001):
            if hotdog_count * i > 1000:
                break
            if hotdog_count * i in bun_counts:
                bun_count = max(bun_count, bun_counts[hotdog_count * i])
        if bun_count > 0:
            min_packs = min(min_packs, hotdog_count + bun_count)

    return min_packs if min_packs != float('inf') else "impossible"

