def solution(n, s, k, r, c):
    dp = [[[float('inf')] * 3 for _ in range(k+1)] for _ in range(n+1)]
    dp[s][0][0] = 0

    for i in range(n, 0, -1):
        for j in range(k+1):
            for color in range(3):
                for prev_color in range(3):
                    if c[i-1] == color:
                        if j >= r[i-1] and prev_color != color:
                            dp[i-1][j][color] = min(dp[i-1][j][color], dp[i][j-r[i-1]][prev_color] + 1)
                    else:
                        dp[i-1][j][color] = min(dp[i-1][j][color], dp[i][j][prev_color])

    return min(dp[0][k])

