def solve(n, k, x, y):
    # Sort points by x-coordinate
    points = sorted(zip(x, y))
    platforms = []

    # Try to place each platform
    for j in range(1, n):
        platform = [points[j-1][0], points[j][0]]
        # Check if the platform can save any points
        if platform[1] - platform[0] <= k:
            platforms.append(platform)

    # If no platforms can be placed, return 0
    if not platforms:
        return 0

    # Find the platform that can save the most points
    max_saved = 0
    for i in range(len(platforms)):
        saved = 1
        # Check points between platforms[i] and platforms[i-1]
        for j in range(i-1, -1, -1):
            if platforms[j][1] >= platforms[i][0]:
                saved += 1
            else:
                break
        for j in range(i+1, len(platforms)):
            if platforms[j][0] <= platforms[i][1]:
                saved += 1
            else:
                break
        max_saved = max(max_saved, saved)

    return max_saved

